[
 {"question":"To which tissue class does cartilage belong?","choices":["Loose connective tissue proper.","Special or specialized connective tissue.","Dense connective tissue proper.","Stratified epithelium."],"answer_index":1},
 {"question":"Which feature makes cartilage resistant to pressure and tension?","choices":["Chondrocytes predominate over the matrix.","A liquid matrix.","Elastic fibers in all cartilage types.","A solid matrix containing chondromucin."],"answer_index":3},
 {"question":"Where are chondrocytes found?","choices":["Within lacunae in the intercellular matrix.","Within bundles of white fibers.","In one row on a basement membrane.","Within continuous multilayered sheets."],"answer_index":0},
 {"question":"Which group represents components found in cartilage matrix?","choices":["Fine white fibers, adipose cells, and chondromucin.","Fine white fibers, chondrocytes, and histamine.","Fine white fibers, chondrocytes within lacunae, and chondromucin.","Fine white fibers, plasma cells, and heparin."],"answer_index":2},
 {"question":"On what basis are cartilage types classified?","choices":["Number of cell rows and shape of superficial layer.","Predominance or density of fibers within the matrix.","Shape and position of nuclei.","Number of cells within lacunae only."],"answer_index":1},
 {"question":"What is another name for hyaline cartilage?","choices":["White fibrocartilage.","Elastic cartilage.","Flexible cartilage.","Glassy cartilage."],"answer_index":3},
 {"question":"Why is the matrix of hyaline cartilage transparent and homogeneous?","choices":["Because its fibers have low density.","Because it lacks chondrocytes.","Because elastic fibers predominate.","Because the cells rest on a basement membrane."],"answer_index":0},
 {"question":"Which cartilage type–location pairing is correct?","choices":["Hyaline cartilage — intervertebral discs.","White fibrocartilage — auricle.","Hyaline cartilage — tracheal wall.","Elastic cartilage — intervertebral discs."],"answer_index":2},
 {"question":"Which cartilage occurs in intervertebral discs, and which fibers predominate?","choices":["Elastic cartilage — elastic fibers.","White fibrocartilage — white fibers.","Hyaline cartilage — low-density white fibers.","White fibrocartilage — elastic fibers."],"answer_index":1},
 {"question":"Which group of features applies to elastic cartilage?","choices":["White fibers predominate, white in color, occurs in auricle.","Low fiber density, transparent, occurs in tracheal wall.","Elastic fibers predominate, yellow, occurs in intervertebral discs.","Elastic fibers predominate, yellow, occurs in auricle."],"answer_index":3},
 {"question":"Which comparison between hyaline cartilage and white fibrocartilage is correct?","choices":["Fiber density is low in hyaline cartilage; white fibers predominate in fibrocartilage.","Elastic fibers predominate in hyaline cartilage; white fibers predominate in fibrocartilage.","White fibers predominate in hyaline cartilage; elastic fibers predominate in fibrocartilage.","Fiber density is low in hyaline cartilage; adipose cells predominate in fibrocartilage."],"answer_index":0},
 {"question":"Which cartilage type–color pairing is correct?","choices":["Elastic cartilage — white; white fibrocartilage — yellow.","Hyaline cartilage — yellow; elastic cartilage — transparent.","White fibrocartilage — white; elastic cartilage — yellow.","White fibrocartilage — transparent; hyaline cartilage — white."],"answer_index":2},
 {"question":"Which statement about cartilage is incorrect?","choices":["Its cells occur within lacunae.","Its matrix is liquid, making it resistant to pressure and tension.","Its matrix contains chondromucin.","It is classified by the predominance or density of fibers in the matrix."],"answer_index":1},
 {"question":"Which comparison between the tracheal lining and its wall cartilage is correct?","choices":["Lining: simple columnar epithelium; cartilage: hyaline.","Lining: pseudostratified columnar epithelium; cartilage: white fibrocartilage.","Lining: stratified columnar epithelium; cartilage: elastic.","Lining: pseudostratified columnar epithelium; cartilage: hyaline."],"answer_index":3},
 {"question":"Which set of pairings is entirely correct?","choices":["Tracheal wall: hyaline cartilage; intervertebral discs: white fibrocartilage; auricle: elastic cartilage.","Tracheal wall: white fibrocartilage; intervertebral discs: hyaline cartilage; auricle: elastic cartilage.","Tracheal wall: hyaline cartilage; intervertebral discs: elastic cartilage; auricle: white fibrocartilage.","Tracheal wall: elastic cartilage; intervertebral discs: white fibrocartilage; auricle: hyaline cartilage."],"answer_index":0}
