INSERT INTO public.teacher_topic_mcqs (teacher_id,topic_key,title,questions)
SELECT 'nadia-al-nuaimy','nadia-en-ch2-lec24-exam','Topic 24 — Bone Tissue',$json$
[
 {"question":"Why is bone harder than cartilage?","choices":["Its matrix contains yellow fibers and chondromucin.","Its matrix contains a high proportion of calcium salts.","Its matrix does not contain white fibers.","Its bone cells contain calcium phosphate."],"answer_index":1},
 {"question":"Which group represents components of bone-tissue matrix?","choices":["Calcium phosphate, calcium carbonate, and white fibers.","Calcium phosphate, calcium carbonate, and yellow fibers.","Calcium salts, chondromucin, and white fibers.","Calcium carbonate, reticular fibers, and chondromucin."],"answer_index":0},
 {"question":"How is bone tissue similar to cartilage?","choices":["Both contain special cells and yellow fibers in a solid matrix.","Both contain chondromucin and calcium salts.","Both contain special cells within lacunae, fine white fibers, and intercellular matrix.","Both consist of arranged lamellae surrounding a central canal."],"answer_index":2},
 {"question":"What are the two types of bone tissue?","choices":["White bone and yellow bone.","Glassy bone and elastic bone.","Peripheral bone and interstitial bone.","Compact bone and spongy bone."],"answer_index":3},
 {"question":"What form does the intercellular substance take in bone?","choices":["Fiber bundles called bone fibrils.","Plates called bone lamellae.","A fiber network called peripheral lamellae.","A mucous substance called bone mucin."],"answer_index":1},
 {"question":"Which description applies to peripheral lamellae in compact bone?","choices":["Lamellae filling spaces between Haversian systems.","Concentric circular lamellae surrounding a Haversian canal.","Irregular lamellae enclosing spaces.","Lamellae parallel to the outer and inner surfaces of bone."],"answer_index":3},
 {"question":"In part of compact bone, concentric bone lamellae surround the:","choices":["Volkmann canal.","Haversian canal.","interstitial lamellae.","bone lacuna."],"answer_index":1},
 {"question":"What is a Haversian system?","choices":["A transverse canal connecting Haversian canals.","Irregular lamellae enclosing marrow-filled spaces.","Concentric bone lamellae in compact bone together with a Haversian canal.","Lamellae filling spaces between the outer and inner bone surfaces."],"answer_index":2},
 {"question":"Which description correctly combines the location and contents of a Haversian canal?","choices":["A central longitudinal canal in compact bone through which blood vessels and nerves pass.","A transverse canal in spongy bone through which osteocytes pass.","A central transverse canal in compact bone through which interstitial lamellae pass.","A longitudinal canal in spongy bone through which white fibers pass."],"answer_index":0},
 {"question":"What is the function of Volkmann canals?","choices":["Connect Haversian systems with peripheral lamellae.","Connect Haversian canals to one another.","Connect interstitial lamellae to one another.","Connect bone marrow to osteocytes."],"answer_index":1},
 {"question":"Which comparison between Haversian and Volkmann canals is correct?","choices":["Haversian canal is transverse; Volkmann canal is central and longitudinal.","Lamellae are concentrically arranged around both canals.","Haversian canal is central and longitudinal; Volkmann canal is transverse.","Blood vessels and nerves pass only through Volkmann canals."],"answer_index":2},
 {"question":"Where are interstitial lamellae found in compact bone?","choices":["Between Haversian systems and between peripheral bone lamellae.","Concentrically around Volkmann canals.","Inside Haversian canals with blood vessels and nerves.","Between spongy-bone spaces and bone marrow."],"answer_index":0},
 {"question":"How do spongy-bone lamellae differ from compact-bone lamellae?","choices":["They form concentric circles around Volkmann canals.","They are peripheral and parallel to the outer and inner bone surfaces.","They form Haversian systems separated by interstitial lamellae.","They are unorganized and form irregular partitions and trabeculae."],"answer_index":3},
 {"question":"What occurs in spaces enclosed between spongy-bone lamellae?","choices":["Blood vessels and nerves only.","Bone marrow.","Chondromucin.","Haversian systems."],"answer_index":1},
 {"question":"Which complete set of features applies to compact bone?","choices":["Unorganized lamellae enclosing marrow-filled spaces and no Haversian systems.","Lamellae arranged in three forms, with Haversian and Volkmann canals and Haversian systems.","Irregular lamellae with Haversian but no Volkmann canals.","Lamellae arranged as partitions and trabeculae; less hard than spongy bone."],"answer_index":1}
]$json$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.teacher_topic_mcqs WHERE teacher_id='nadia-al-nuaimy' AND topic_key='nadia-en-ch2-lec24-exam');
